#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=12

# Run from the repo root on the dev PC, in Git Bash: values land in the repo's .env.
cd "$(dirname "$0")/.."
REMOTE=/srv/inventory
export MSYS_NO_PATHCONV=1
# ssh to the server; -t when the command needs sudo's password.
on_server() { ssh -o ConnectTimeout=10 "$SERVER_USER@$SERVER_IP" "$@"; }
on_server_tty() { ssh -t -o ConnectTimeout=10 "$SERVER_USER@$SERVER_IP" "$@"; }

banner "Inventory: first server setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "This sets up the home server once (spec §11). You'll need:"
step "The Ubuntu server installed, plugged into the home network, with a screen and keyboard for now."
step "Its login name and password (the one you made when installing Ubuntu)."
step "The USB drive for backups (it may be erased in stage 7; you'll be asked first)."
step "Your password manager open: two passwords get saved there."
step "Access to the home router's admin page."
say ""
step "On the server's own keyboard, make sure SSH is installed:"
note "    sudo apt update && sudo apt install -y openssh-server"
ask SERVER_USER "The server's login name (e.g. admin):"
write_env SERVER_USER "$SERVER_USER"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Router: reserve the server's address"
say "Phones find the server by a fixed address, so the router must always give it the same one."
step "On the server's keyboard, run:  ip -4 addr show   and   ip link"
step "Note its current address (inet 192.168.x.y) and its MAC address (link/ether aa:bb:cc:…)"
ask ROUTER_URL "The router's admin page [e.g. http://192.168.1.1]:"
write_env ROUTER_URL "$ROUTER_URL"
open_url "$ROUTER_URL"
step "Log in, then find DHCP → Address reservation (some routers call it Static lease or Fixed IP)."
step "Add a reservation: the server's MAC address → its current address. Save."
ask SERVER_IP "The reserved address (e.g. 192.168.1.10):"
write_env SERVER_IP "$SERVER_IP"
write_env DEPLOY_HOST "$SERVER_USER@$SERVER_IP"
note "If the address ever changes, every phone has to pair again."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "SSH key from this PC"
say "Deploys and backups use an SSH key, so no password is typed each time."
if [[ ! -f "$HOME/.ssh/id_ed25519" ]]; then
  step "Making a key for this PC (press Enter at each question)…"
  ssh-keygen -t ed25519 -f "$HOME/.ssh/id_ed25519" -C "inventory-dev-pc"
fi
if ssh -o BatchMode=yes -o ConnectTimeout=10 "$SERVER_USER@$SERVER_IP" true 2>/dev/null; then
  say "✓ This PC can already log in with its key."
else
  step "Copying the key to the server: type the server's password once."
  ssh -o StrictHostKeyChecking=accept-new "$SERVER_USER@$SERVER_IP" \
    'mkdir -p ~/.ssh && chmod 700 ~/.ssh && cat >> ~/.ssh/authorized_keys && chmod 600 ~/.ssh/authorized_keys' < "$HOME/.ssh/id_ed25519.pub"
  ssh -o BatchMode=yes "$SERVER_USER@$SERVER_IP" true && say "✓ Key login works."
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Docker on the server"
if on_server 'docker compose version' >/dev/null 2>&1; then
  say "✓ Docker is already installed."
else
  say "Installing Docker with Docker's official script (it asks for the server's password)."
  on_server_tty 'curl -fsSL https://get.docker.com -o /tmp/get-docker.sh && sudo sh /tmp/get-docker.sh && sudo usermod -aG docker "$USER"'
  say "Docker is installed; logging in again so the docker group applies."
fi
on_server 'docker compose version' && say "✓ Docker Compose answers."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Data folder and server settings"
say "Everything the server keeps lives in $REMOTE: db, photos, apk, backups."
on_server_tty "sudo mkdir -p $REMOTE/db $REMOTE/photos $REMOTE/apk $REMOTE/backups $REMOTE/scripts && sudo chown -R \"\$USER\": $REMOTE"
if on_server "test -f $REMOTE/.env"; then
  say "✓ $REMOTE/.env already exists; keeping it."
else
  db_password=$(openssl rand -hex 24)
  on_server "umask 077 && cat > $REMOTE/.env" <<EOF
# Server settings (spec §11). Not in git. APP_VERSION and PREVIOUS_APP_VERSION are kept by deploys.
POSTGRES_PASSWORD=$db_password
TZ=Asia/Kuala_Lumpur
PUBLIC_ADDRESS=http://$SERVER_IP
APP_VERSION=
PREVIOUS_APP_VERSION=
EOF
  say "✓ Wrote $REMOTE/.env with a new database password."
  step "Save the database password in your password manager as \"Inventory database\":"
  note "    $db_password"
  pause "Press Enter once it's saved"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Firewall: only the home network, only web and SSH"
LAN_SUBNET_DEFAULT="${SERVER_IP%.*}.0/24"
say "ufw will allow port 80 (the app) and SSH, from the home network only."
ask LAN_SUBNET "The home network [Enter for $LAN_SUBNET_DEFAULT]:"
LAN_SUBNET=${LAN_SUBNET:-$LAN_SUBNET_DEFAULT}
write_env LAN_SUBNET "$LAN_SUBNET"
warn "Check this PC's address is inside $LAN_SUBNET, or SSH will be cut off."
if confirm "Turn the firewall on now"; then
  on_server_tty "sudo ufw default deny incoming && sudo ufw default allow outgoing \
    && sudo ufw allow from $LAN_SUBNET to any port 22 proto tcp \
    && sudo ufw allow from $LAN_SUBNET to any port 80 proto tcp \
    && sudo ufw --force enable && sudo ufw status verbose"
else
  SKIPPED+=("Firewall: run stage 6 again when ready")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "USB backup drive"
say "Plug the backup drive into the server. Its partitions:"
on_server 'lsblk -o NAME,SIZE,FSTYPE,LABEL,MOUNTPOINT'
ask USB_PARTITION "The drive's partition (e.g. sdb1):"
write_env USB_PARTITION "$USB_PARTITION"
fstype=$(on_server "lsblk -no FSTYPE /dev/$USB_PARTITION" | tr -d '[:space:]')
if [[ "$fstype" != "ext4" ]]; then
  warn "/dev/$USB_PARTITION is '${fstype:-empty}', not ext4. It must be formatted: EVERYTHING ON IT IS ERASED."
  if confirm "Erase /dev/$USB_PARTITION and format it as ext4"; then
    on_server_tty "sudo umount /dev/$USB_PARTITION 2>/dev/null; sudo mkfs.ext4 -F -L inventory-backup /dev/$USB_PARTITION"
  else
    SKIPPED+=("USB drive: format it as ext4, then run stage 7 again")
  fi
fi
uuid=$(on_server "lsblk -no UUID /dev/$USB_PARTITION" | tr -d '[:space:]')
if [[ -n "$uuid" ]]; then
  # nofail: the server still starts without the drive; backups then say "USB drive not mounted".
  on_server_tty "sudo mkdir -p /mnt/inventory-usb \
    && (grep -q '$uuid' /etc/fstab || echo 'UUID=$uuid /mnt/inventory-usb ext4 defaults,nofail 0 2' | sudo tee -a /etc/fstab) \
    && sudo systemctl daemon-reload && sudo mount -a \
    && sudo touch /mnt/inventory-usb/.inventory-backups && sudo chown -R \"\$USER\": /mnt/inventory-usb \
    && df -h /mnt/inventory-usb"
  say "✓ Mounted at /mnt/inventory-usb, marked for backups."
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "The app's release signing key"
say "Every app update must be signed with this one key, made once and kept on this PC outside the repo."
warn "Losing it means uninstalling the app on every phone. Keep the password and a copy safe."
keystore="$HOME/.inventory/inventory-release.keystore"
JAVA_HOME=${JAVA_HOME:-$LOCALAPPDATA/Programs/Temurin/jdk-17.0.21+9}
if [[ -f "$keystore" ]]; then
  say "✓ The key already exists: $keystore"
else
  mkdir -p "$(dirname "$keystore")"
  ask_secret KEY_PASSWORD "Choose the key's password (8+ characters; it isn't shown):"
  ask_secret KEY_PASSWORD_AGAIN "Type it again:"
  if [[ "$KEY_PASSWORD" != "$KEY_PASSWORD_AGAIN" || ${#KEY_PASSWORD} -lt 8 ]]; then
    warn "The passwords differ or are too short. Run the wizard again."
    exit 1
  fi
  "$JAVA_HOME/bin/keytool" -genkeypair -keystore "$keystore" -alias inventory -keyalg RSA -keysize 4096 \
    -validity 36500 -storepass "$KEY_PASSWORD" -keypass "$KEY_PASSWORD" -dname "CN=Household Inventory"
  unset KEY_PASSWORD KEY_PASSWORD_AGAIN
  say "✓ Made $keystore"
  step "Save the password in your password manager now, as \"Inventory app signing key\"."
  pause "Press Enter once it's saved"
fi
write_env INVENTORY_KEYSTORE "$(cygpath -w "$keystore" 2>/dev/null || echo "$keystore")"
write_env INVENTORY_KEY_ALIAS "inventory"
note "The password is never written to disk: building the APK asks for it."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Windows Firewall on this PC (for development)"
say "Lets phones on the home Wi-Fi reach the dev server on this PC (ports 3000, 5173 and 8080, private networks only)."
if confirm "Add the rule now (Windows asks for permission)"; then
  powershell.exe -NoProfile -Command "Start-Process powershell -Verb RunAs -Wait -ArgumentList '-NoProfile','-Command',\"if (-not (Get-NetFirewallRule -DisplayName 'Inventory dev' -ErrorAction SilentlyContinue)) { New-NetFirewallRule -DisplayName 'Inventory dev' -Direction Inbound -Protocol TCP -LocalPort 3000,5173,8080 -Profile Private -Action Allow }\""
  say "✓ Rule \"Inventory dev\" in place."
else
  SKIPPED+=("Windows Firewall rule for development (stage 9)")
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "First deploy"
say "Builds the APK (signed with the new key) and the server image, ships both and starts them."
note "It takes a while: the APK build alone is 15–40 minutes."
export JAVA_HOME ANDROID_HOME=${ANDROID_HOME:-$LOCALAPPDATA/Android/Sdk}
if confirm "Deploy now"; then
  pnpm run deploy
  for _ in $(seq 1 30); do curl -sf "http://$SERVER_IP/health" >/dev/null && break; sleep 2; done
  if curl -sf "http://$SERVER_IP/health" >/dev/null; then
    say "✓ http://$SERVER_IP/ answers."
    open_url "http://$SERVER_IP/"
  else
    warn "The server doesn't answer yet. On the server: cd $REMOTE && docker compose logs app"
  fi
  step "Commit the version bump the deploy made (apps/mobile/app.json and the package.json files)."
else
  SKIPPED+=("First deploy: pnpm run deploy")
fi
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Test a restore"
say "A backup is only as good as a restore. This backs up now, then restores that backup."
on_server "cd $REMOTE && docker compose exec -T app /app/ops/backup.sh manual" || warn "The backup reported a problem."
latest=$(on_server "ls $REMOTE/backups | grep manual | tail -1")
say "On the USB drive:"
on_server "ls /mnt/inventory-usb/inventory | tail -3"
if [[ -n "$latest" ]] && confirm "Restore $latest now (nothing has changed since, so nothing is lost)"; then
  on_server_tty "INVENTORY_DIR=$REMOTE $REMOTE/scripts/restore.sh --yes $latest"
  for _ in $(seq 1 30); do curl -sf "http://$SERVER_IP/health" >/dev/null && break; sleep 2; done
  curl -sf "http://$SERVER_IP/health" >/dev/null && say "✓ Restored, and the server answers."
  curl -s "http://$SERVER_IP/web/server"; printf '\n'
  note "The footer on http://$SERVER_IP/ should say the last backup is fine."
else
  SKIPPED+=("Test restore (stage 11)")
fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Copies off the server"
say "The dev PC keeps a copy of the backups, and the signing key goes with them."
BACKUP_COPY_DIR=${BACKUP_COPY_DIR:-backups-from-server}
pnpm run backups:pull
cp "$keystore" "$BACKUP_COPY_DIR/" && say "✓ Copied the signing key to $BACKUP_COPY_DIR/"
step "Also keep that folder somewhere off this PC (an external drive or cloud storage you trust)."
step "Run  pnpm run backups:pull  now and then."
pause

finish
say "The server answers at http://$SERVER_IP/ and phones can get the app at http://$SERVER_IP/app."
}

run_wizard "$@"; exit
